func BenchmarkEncodeDecodeBaseField(b *testing.B) {
	seed := fullyPopulatedBaseField
	w := orc.NewWriter(0)
	r := orc.NewReader(nil)
	for b.Loop() {
		w.Reset()
		if err := seed.EncodeOrc(w); err != nil {
			b.Fatal(err)
		}
		var decoded v0.BaseField
		r.ResetBytes(w.Bytes())
		if err := decoded.DecodeOrc(r); err != nil {
			b.Fatal(err)
		}
	}
}

